  motivo?: string
): Promise<boolean> {
  try {
    await atualizarPerfilSupabase(userId, {
      bloqueado,
      motivo_bloqueio: motivo || null,
    });
    return true;
  } catch (err) {
    console.error("Erro ao alterar bloqueio:", err);
    return false;
  }
}

